# Homebrew formula for yag.
#
# GENERATED by rules_brew -- do not edit by hand;
# the next release overwrites this file.
class Yag < Formula
  desc "Workspace-sync git tooling: land, sync, fold, mend"
  homepage "https://github.com/qzmfranklin/homebrew-tap"
  # Platform choice lives in the argument, not in an on_macos block:
  # brew does not allow `url`/`sha256` inside an on_system block.
  # macOS is one universal (arm64 + x86_64) binary, so it needs no arch split.
  url on_system_conditional(
    macos: "https://github.com/qzmfranklin/homebrew-tap/releases/download/yag-0.10.0/yag-darwin-universal.tar.xz",
    linux: on_arch_conditional(
      arm:   "https://github.com/qzmfranklin/homebrew-tap/releases/download/yag-0.10.0/yag-linux-arm64.tar.xz",
      intel: "https://github.com/qzmfranklin/homebrew-tap/releases/download/yag-0.10.0/yag-linux-amd64.tar.xz",
    ),
  )
  version "0.10.0"
  sha256 on_system_conditional(
    macos: "79206134fe82940bbc1f2766d70c9d0d79d25debb4c31c27871c8ebc6152a62a",
    linux: on_arch_conditional(
      arm:   "c2f1928bc8564132e886ad8c3135a2116883e2bfa59ba9e84af75c1327aa4bac",
      intel: "14d0bcb2f32e7531391c93a3e8d5e4d95f7b30f1ec229a9e1ce900da262ac8c8",
    ),
  )
  license :cannot_represent

  def install
    bin.install "yag"

    # Ad-hoc codesign on macOS. This is INTENTIONAL and load-bearing, not a
    # workaround: the binary is unsigned, and macOS refuses to exec an unsigned
    # or stale-signed Mach-O. Writing the file also invalidates any prior
    # signature, so it must be re-signed after install.
    #
    # chmod first: Homebrew stages files read-only, and both xattr and codesign
    # need to WRITE to the binary (xattr fails with EACCES otherwise).
    if OS.mac?
      chmod 0755, bin/"yag"
      system "/usr/bin/xattr", "-cr", bin/"yag"
      system "/usr/bin/codesign", "--force", "--sign", "-", bin/"yag"
    end

    # `--print SHELL` writes the script to STDOUT and installs nothing; a
    # bare `yag complete` would edit the user's rc file, which a
    # formula must not do.
    #
    # generate_completions_from_executable appends the shell name as the
    # final argument and writes each script where brew expects it, so it
    # replaces one hand-rolled safe_popen_read per shell.
    generate_completions_from_executable(
      bin/"yag",
      "complete",
      "--print",
      shells: [:bash, :zsh],
    )
  end

  def post_install
    linked = HOMEBREW_PREFIX/"bin/yag"
    if linked.exist? && !linked.symlink?
      opoo <<~EOS
        Replacing a non-Homebrew yag at #{linked}.
        That file was almost certainly left by the legacy install script.
        The Homebrew-managed yag is now the one on your PATH.
      EOS
      linked.unlink
    end

    # Idempotent, and also repairs the case where the legacy binary was
    # deleted by hand: brew never created the symlink, so the tool was
    # missing from PATH entirely.
    linked.make_relative_symlink(bin/"yag") unless linked.symlink?
  end


  def caveats
    mac = on_macos do
      <<~EOS
        yag requires git 2.38 or newer: the land/sync/fold merge machinery runs
        `git merge-tree --write-tree`, which older git does not have. Check with
        `git version`; the macOS system git from a current Xcode Command Line Tools
        is new enough, and `brew install git` provides a newer one otherwise.

        Homebrew installs shell completions for bash and zsh, but it never edits
        your rc files: they take effect in new shells, so restart your terminal
        (or open a new tab) after installing for `yag <TAB>` completion to work.
      EOS
    end
    linux = on_linux do
      <<~EOS
        yag requires git 2.38 or newer: the land/sync/fold merge machinery runs
        `git merge-tree --write-tree`, which older git does not have. Check with
        `git version` and upgrade your distribution's git if it is older.

        yag ships as a single prebuilt binary per arch and runs on ubuntu22 and
        newer (glibc >= 2.35). On hosts with glibc < 2.39 (Ubuntu 22.04 and
        older), Homebrew adds gcc and glibc as implicit dependencies to every
        formula and would build them from source; yag's formula carries no real
        dependencies, so install it there with:

          brew install --ignore-dependencies yag

        On glibc >= 2.39 hosts (Ubuntu 24.04+, Homebrew's own supported set),
        plain `brew install yag` works with no extra pulls.
      EOS
    end
    mac || linux
  end

  test do
    # --help smokes only: the verbs operate on real git repositories and are not
    # formula-tested. Assert on the usage line, which survives argument changes,
    # rather than on about text.
    assert_match(/Usage: yag/, shell_output("#{bin}/yag --help"))
    assert_match(/Usage: yag land/, shell_output("#{bin}/yag land --help"))
  end
end
